contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt to call getTokens sending `amount` wei. We observe before/after via public getters.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        address tester = address(this);
        uint256 balBefore = c.balanceOf(tester); if (__ESBMC_reverted()) return;
        bool blackBefore = c.blacklist(tester); if (__ESBMC_reverted()) return;
        uint256 distributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 remainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;

        bool reverted;
        // State-changing call must be a top-level statement
        c.getTokens{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balanceOf(tester); if (__ESBMC_reverted()) return;
        bool blackAfter = c.blacklist(tester); if (__ESBMC_reverted()) return;
        uint256 distributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 remainingAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;

        // Exactly one assert expressing the general invariant.
        assert(
            (
                // If reverted: observable values unchanged
                reverted &&
                balAfter == balBefore &&
                blackAfter == blackBefore &&
                distributedAfter == distributedBefore &&
                remainingAfter == remainingBefore
            )
            ||
            (
                // If succeeded: caller becomes blacklisted, balance did not decrease,
                // totalDistributed increased by at least the caller's balance gain, and totalRemaining did not increase.
                !reverted &&
                blackAfter == true &&
                balAfter >= balBefore &&
                distributedAfter >= distributedBefore &&
                // distributed increase covers caller gain: (distributedAfter - distributedBefore) >= (balAfter - balBefore)
                (distributedAfter - distributedBefore) >= (balAfter - balBefore) &&
                // totalRemaining cannot increase when tokens distributed
                remainingAfter <= remainingBefore
            )
        );
    }

    receive() external payable {}
}

