pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address tester = address(this);
        uint256 balBefore;
        try c.balanceOf(tester) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool blackBefore;
        try c.blacklist(tester) returns (bool __r) { blackBefore = __r; } catch { return; }
        uint256 distributedBefore;
        try c.totalDistributed() returns (uint256 __r) { distributedBefore = __r; } catch { return; }
        uint256 remainingBefore;
        try c.totalRemaining() returns (uint256 __r) { remainingBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balanceOf(tester) returns (uint256 __r) { balAfter = __r; } catch { return; }
        bool blackAfter;
        try c.blacklist(tester) returns (bool __r) { blackAfter = __r; } catch { return; }
        uint256 distributedAfter;
        try c.totalDistributed() returns (uint256 __r) { distributedAfter = __r; } catch { return; }
        uint256 remainingAfter;
        try c.totalRemaining() returns (uint256 __r) { remainingAfter = __r; } catch { return; }
        assertTrue((
                // If reverted: observable values unchanged
                reverted &&
                balAfter == balBefore &&
                blackAfter == blackBefore &&
                distributedAfter == distributedBefore &&
                remainingAfter == remainingBefore
            )
            ||
            (
                // If succeeded: caller becomes blacklisted, balance did not decrease,
                // totalDistributed increased by at least the caller's balance gain, and totalRemaining did not increase.
                !reverted &&
                blackAfter == true &&
                balAfter >= balBefore &&
                distributedAfter >= distributedBefore &&
                // distributed increase covers caller gain: (distributedAfter - distributedBefore) >= (balAfter - balBefore)
                (distributedAfter - distributedBefore) >= (balAfter - balBefore) &&
                // totalRemaining cannot increase when tokens distributed
                remainingAfter <= remainingBefore
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
